<?php get_header(); ?><section class="ga-section"><div class="ga-container"><?php while(have_posts()):the_post();?><article <?php post_class(); ?>><p class="ga-meta"><?php echo esc_html(get_the_date()); ?> · <?php the_author(); ?></p><h1 class="ga-heading"><?php the_title(); ?></h1><?php if(has_post_thumbnail()){the_post_thumbnail('large');}?><div class="ga-content"><?php the_content(); ?></div></article><?php endwhile;?><section class="ga-section"><h2 class="ga-heading">Outros conteúdos</h2><div class="ga-posts"><?php $related=new WP_Query(array('post_type'=>'post','post_status'=>'publish','posts_per_page'=>3,'post__not_in'=>array(get_the_ID()),'no_found_rows'=>true));while($related->have_posts()):$related->the_post();?><article class="ga-post-card"><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(get_the_excerpt()); ?></p></article><?php endwhile;wp_reset_postdata();?></div></section></div></section><?php get_footer(); ?>